        best_score = None
        for c in corners:
            score = manhattan(c, opp_pos)
            if best_score is None or score > best_score:
                best_score = score
                target = c
        return bounded_move(self_pos, target if target is not None else self_pos)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("neutral_cells")
            or observation.get("opponent_territory")
            or observation.get("targets")
            or []
        )
