                best = tp
        if best is not None:
            return bounded_move(self_pos, best)

        if isinstance(grid_w, int) and isinstance(grid_h, int) and grid_w > 0 and grid_h > 0:
            center = (grid_w // 2, grid_h // 2)
            return bounded_move(self_pos, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for r in resources:
        rp = safe_pos(r, None)
        if rp is None:
            continue
        # Prefer closer resources, but slightly favor those the opponent is farther from.
        score = manhattan(self_pos, rp) * 2 - manhattan(opp_pos, rp)
        if best_score is None or score < best_score:
            best_score = score
            best = rp

    if best is not None:
        return bounded_move(self_pos, best)

    if env == "resource_collection":
        if isinstance(grid_w, int) and isinstance(grid_h, int) and grid_w > 0 and grid_h > 0:
            center = (grid_w // 2, grid_h // 2)
            return bounded_move(self_pos, center)
